// Puts the reference for AI assistants into the plugin.
//
// The reference is one Markdown file at the top of the repository:
// "AI helper/Spellbook for AI assistants.md". That file is the source. The
// plugin's command "Create AI helper note" writes the same text into a
// project, so the build copies the text into a small TypeScript module that
// the plugin bundles. That module is generated: it is kept in git so that
// the tests and the type check work without a build, and a test fails when
// it no longer says what the Markdown file says. Do not edit it by hand:
// change the Markdown file and run "npm run build" (or this script).

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

/** The reference, relative to the repository root: the one source of the text. */
export const HELPER_SOURCE = 'AI helper/Spellbook for AI assistants.md';

/** The generated module, relative to the repository root. */
export const HELPER_MODULE = 'src/features/aihelper/referenceText.ts';

/**
 * The text as the plugin ships it: line breaks as "\n", and exactly one at
 * the end.
 *
 * @param {string} markdown the Markdown file as it was read
 * @returns {string}
 */
export function helperText(markdown) {
  const text = markdown.charCodeAt(0) === 0xfeff ? markdown.slice(1) : markdown;
  return `${text.replace(/\r\n?/g, '\n').replace(/\s+$/, '')}\n`;
}

/**
 * The generated module for a text.
 *
 * @param {string} markdown the Markdown file as it was read
 * @returns {string}
 */
export function helperModule(markdown) {
  return [
    '// The reference for AI assistants, as the plugin ships it.',
    '//',
    `// This file is generated by scripts/aihelper.mjs from "${HELPER_SOURCE}".`,
    '// Do not edit it by hand: change that file and run "npm run build".',
    '',
    '/** The whole text of the note that "Create AI helper note" writes. */',
    `export const HELPER_TEXT: string = ${JSON.stringify(helperText(markdown))};`,
    '',
  ].join('\n');
}

/**
 * Read the reference and give the module it makes.
 *
 * @param {string} repoRoot absolute path of the plugin repository
 * @returns {string}
 */
export function readHelperModule(repoRoot) {
  return helperModule(readFileSync(path.join(repoRoot, HELPER_SOURCE), 'utf8'));
}

/**
 * Write the generated module, unless it already says exactly that.
 *
 * @param {string} repoRoot absolute path of the plugin repository
 * @returns {string} the path that was written
 */
export function writeHelperModule(repoRoot) {
  const output = path.join(repoRoot, HELPER_MODULE);
  const text = readHelperModule(repoRoot);
  let current = null;
  try {
    current = readFileSync(output, 'utf8');
  } catch {
    current = null;
  }
  if (current !== text) writeFileSync(output, text, 'utf8');
  return output;
}

// Run by itself ("node scripts/aihelper.mjs"), it writes the module.
if (process.argv[1] !== undefined && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  writeHelperModule(path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..'));
  console.log(`  ${HELPER_MODULE}  written from "${HELPER_SOURCE}"`);
}
